<script>
(() => {
    document.querySelectorAll('.receipt-toggle').forEach((toggle) => {
        const row = toggle.closest('div.grid');
        const fields = row.querySelectorAll('input[name^="items["]');
        const sync = () => fields.forEach((field) => { field.disabled = !toggle.checked; });
        toggle.addEventListener('change', sync);
        sync();
    });
})();
</script>
